def describe(name: str) -> tuple[str, str, str, str] | None:
    """(category, scenario code, title, what is checked) for a pytest name or node id, or None."""
    short = name.split("::")[-1]
    for prefix in sorted(SCENARIOS, key=len, reverse=True):
        if short.startswith(prefix):
            return SCENARIOS[prefix]
    return None
